// This file is generated by AI.

// `watchValues` 的比较判据测试。
//
// 它要保住的是"只有我关心的字段变化时才动手"这一语义 —— 用错的话表现是编辑器反复重建、或会话被无谓地
// 反复写盘。
//
// ⚠️ 这里**只测纯函数 `valuesEqual`**。观察者本身是一个 `$effect` (跑在 `$effect.root` 里), 而 vitest
// 跑在 SSR 模式 (`generate: 'server'`), 那种模式下的 rune 是惰性的: `$effect` 不会执行、`$state` 也不
// 建立依赖。所以"改了状态真的会回调"这一条只能在浏览器里验证, 在这里写只会得到一条**假绿**的用例。
//
// 还有一条结构性事实值得钉住: 观察者**不创建任何定时器**, 它靠 Svelte 的依赖追踪唤醒。

import { describe, expect, it } from 'vitest';

import { valuesEqual } from '../src/state/watch.svelte';

describe('valuesEqual', () => {
  it('相同的取值算"没变"', () => {
    expect(valuesEqual([1, 'a', true], [1, 'a', true])).toBe(true);
  });

  it('任意一项不同就算"变了"', () => {
    expect(valuesEqual([1, 'b', true], [1, 'a', true])).toBe(false);
    expect(valuesEqual([2, 'a', true], [1, 'a', true])).toBe(false);
    expect(valuesEqual([1, 'a', false], [1, 'a', true])).toBe(false);
  });

  it('长度不同算"变了"（多一个/少一个字段）', () => {
    expect(valuesEqual([1, 'a'], [1, 'a', true])).toBe(false);
    expect(valuesEqual([1, 'a', true], [1, 'a'])).toBe(false);
  });

  it('按引用比较: 同一个实例算没变, 值相同的新实例算变了', () => {
    const same = { content: 'a' };
    // 这正是"编辑器不因无关变化重建"的判据: 读回同一个实例不该触发
    expect(valuesEqual([same], [same])).toBe(true);
    // 而 store 里常见的"整份替换"是**新实例** —— 判据仍按引用, 因此会触发回调;
    // 于是"值没变就别动 DOM"必须由回调自己按值判断 (例如 `applyDiagnostics` 的签名比较)
    expect(valuesEqual([{ content: 'a' }], [{ content: 'a' }])).toBe(false);
  });

  it('`NaN` 与 `NaN` 算没变, `+0` 与 `-0` 算变了（`Object.is` 语义）', () => {
    expect(valuesEqual([NaN], [NaN])).toBe(true);
    expect(valuesEqual([0], [-0])).toBe(false);
  });

  it('空数组算没变（没有要看的字段）', () => {
    expect(valuesEqual([], [])).toBe(true);
  });
});
